SELECT p.gender, CAST(p.anchor_age AS INT) AS age, h.hadm_id, i.careunit, i.los, COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN p.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS mortality_rate, SUM(CASE WHEN d.icd_code = '195.0' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS ckd_prevalence, SUM(CASE WHEN d.icd_code = '230.0' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS diabetes_prevalence FROM patients p JOIN admissions h ON p.subject_id = h.subject_id JOIN icustays i ON h.stay_id = i.stay_id JOIN diagnoses_icd d ON h.hadm_id = d.hadm_id WHERE p.gender = 'F' AND CAST(p.anchor_age AS INT) BETWEEN 80 AND 90 AND h.admission_type = 'heart failure' AND i.careunit IN ('ICU', 'non-ICU') AND i.los BETWEEN 0 AND 8 GROUP BY p.gender, age, h.hadm_id, i.careunit, i.los ORDER BY p.gender, age, h.hadm_id, i.careunit, i.los NULLS LAST;